// T-31 P1a — generate the Rust `rpc` method allow-list from docs/migration/api-inventory.json.
//
// The `rpc` command must only serve methods the frozen inventory exposes. Rather than hand-maintain a
// second list that can drift, derive it from the inventory (the single source of truth) and check the
// generated file in; scripts/check-tauri-allowlist.mjs fails if the committed file differs.
//
// Only invoke- and send-kind names go through `invoke('rpc', …)`; event-kind names use the Tauri event
// channel and are never sent as rpc methods.
//
// Parity 11-2: a name the inventory marks `guestOnly` is exposed to ONE guest webview's own bridge, never to the
// main renderer. Those names are generated into GUEST_ONLY_METHODS and excluded from ALLOWED_METHODS, so the main
// `rpc` command can never forward them to the sidecar. Since 0.3.0-alpha.11 (the wardrobe, the only such guest,
// removed) the inventory marks none, so the list is generated empty.
//
// Usage: node tauri/gen-allowlist.mjs [--out tauri/src-tauri/src/rpc_allow_list.rs]
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const INVENTORY = path.join(root, 'docs', 'migration', 'api-inventory.json');
const OUT = path.join(here, 'src-tauri', 'src', 'rpc_allow_list.rs');

/** Every inventory invoke/send name, guest-only ones included (sorted, deterministic). */
export function rpcMethodNames(inventory) {
  return (inventory.apis || [])
    .filter((a) => a.kind === 'invoke' || a.kind === 'send')
    .map((a) => a.name)
    .sort();
}

/** The inventory names exposed to a guest webview's own bridge and NEVER to the main renderer. The one
 *  flag lives in the inventory, so the exclusion cannot drift from the API contract. */
export function guestOnlyMethodNames(inventory) {
  return (inventory.apis || [])
    .filter((a) => (a.kind === 'invoke' || a.kind === 'send') && a.guestOnly === true)
    .map((a) => a.name)
    .sort();
}

/** The names the main `rpc` command may serve: every invoke/send name minus the guest-only set. */
export function rendererMethodNames(inventory) {
  const guestOnly = new Set(guestOnlyMethodNames(inventory));
  return rpcMethodNames(inventory).filter((name) => !guestOnly.has(name));
}

/** The inventory event channels the sidecar may push to the renderer (sorted, deduplicated). */
export function eventChannelNames(inventory) {
  return [...new Set((inventory.apis || []).filter((a) => a.kind === 'event').map((a) => a.channel))].sort();
}

/** Renderer -> host reply channels (inventory `channels[]`, kind send, from renderer), e.g. `gesture:result`. Not
 *  rpc methods: the host maps each to a host-only sidecar method (lib.rs reply_target). Sorted, deduplicated. */
export function replyChannelNames(inventory) {
  return [...new Set((inventory.channels || []).filter((c) => c.kind === 'send' && c.from === 'renderer').map((c) => c.channel))].sort();
}

/** Generate the Rust source for the allow-lists (rpc methods, guest-only methods, then push-event channels). */
export function generateAllowList(inventory) {
  const names = rendererMethodNames(inventory);
  const lines = names.map((n) => `    ${JSON.stringify(n)},`);
  const guestLines = guestOnlyMethodNames(inventory).map((n) => `    ${JSON.stringify(n)},`);
  const channels = eventChannelNames(inventory).map((c) => `    ${JSON.stringify(c)},`);
  const replies = replyChannelNames(inventory).map((c) => `    ${JSON.stringify(c)},`);
  return `// GENERATED by tauri/gen-allowlist.mjs from docs/migration/api-inventory.json — do not edit by hand.
//
// The rpc command only serves methods the frozen inventory exposes (the invoke + send kinds; events use
// the Tauri event channel, never rpc). Every other name is rejected before it reaches the sidecar.
pub const ALLOWED_METHODS: &[&str] = &[
${lines.join('\n')}
];

// Parity 11-2: names the inventory marks guestOnly. They are NOT in the main renderer's allow-list. The
// one guest that owns each name would get it through its own bridge command and ACL capability; none exists since
// 0.3.0-alpha.11 (the wardrobe bridge removed), so the list is empty.
pub const GUEST_ONLY_METHODS: &[&str] = &[
${guestLines.join('\n')}
];

// The event channels a sidecar \`event\` notification may name (events.rs). Same source, same rule: a channel
// the inventory does not list is dropped by the host before it reaches the renderer.
pub const ALLOWED_EVENT_CHANNELS: &[&str] = &[
${channels.join('\n')}
];

// Renderer -> host reply channels (the inventory's channels[]). Never rpc methods: lib.rs maps each to a host-only
// sidecar method, so the page cannot name a __host method itself.
pub const ALLOWED_REPLY_CHANNELS: &[&str] = &[
${replies.join('\n')}
];
`;
}

function main() {
  const args = process.argv.slice(2);
  const at = args.indexOf('--out');
  const out = at >= 0 ? path.resolve(args[at + 1]) : OUT;
  const inventory = JSON.parse(fs.readFileSync(INVENTORY, 'utf8'));
  fs.writeFileSync(out, generateAllowList(inventory));
  console.log(`gen-allowlist: wrote ${path.relative(root, out)} (${rendererMethodNames(inventory).length} methods, ${guestOnlyMethodNames(inventory).length} guest-only)`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
